package com.gk.jobhelper.service;
import java.util.*;import org.springframework.stereotype.Component;
@Component public class RecruitmentExcelHeaderNormalizer {public String normalize(String h){String v=h==null?"":h.replaceAll("\\s","").replaceAll("[（）()]","");if(any(v,"岗位名称","招聘岗位","职位名称","岗位","职位"))return "POSITION_NAME";if(any(v,"招聘人数","人数","需求人数","计划人数"))return "RECRUIT_COUNT";if(any(v,"招聘单位","用人单位","所属公司","公司名称","单位"))return "ORGANIZATION";if(any(v,"部门","用人部门","所属部门"))return "DEPARTMENT";if(any(v,"岗位代码","职位代码","岗位编号","职位编号"))return "POSITION_CODE";if(any(v,"学历","学历要求","最低学历"))return "EDUCATION";if(any(v,"学位","学位要求"))return "DEGREE";if(any(v,"专业","专业要求","专业类别"))return "MAJOR";if(any(v,"年龄","年龄要求"))return "AGE";if(any(v,"工作年限","工作经验","工作经历要求"))return "WORK_EXPERIENCE";if(any(v,"任职要求","资格条件","岗位要求","任职资格"))return "REQUIREMENT";if(any(v,"工作地点","工作地区","招聘地点","工作城市"))return "WORK_LOCATION";if(any(v,"岗位职责","工作职责","职位职责"))return "RESPONSIBILITY";return null;}private boolean any(String h,String... values){for(String v:values)if(h.equals(v))return true;return false;}}
